PRAGMA foreign_keys=ON; CREATE TABLE social_accounts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,provider TEXT NOT NULL,provider_account_id TEXT NOT NULL,token_ciphertext BLOB NOT NULL,selected INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(provider,provider_account_id)); CREATE TABLE oauth_states(state_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,provider TEXT NOT NULL,redirect_uri TEXT NOT NULL,expires_at TEXT NOT NULL,consumed_at TEXT); CREATE TABLE hashtag_searches(account_id TEXT NOT NULL REFERENCES social_accounts(id),normalized_hashtag TEXT NOT NULL,searched_at TEXT NOT NULL); CREATE INDEX hashtag_window ON hashtag_searches(account_id,searched_at); CREATE TABLE hashtag_media_cache(provider_hashtag_id TEXT NOT NULL,result_type TEXT NOT NULL CHECK(result_type IN('top','recent')),payload_json TEXT NOT NULL,expires_at TEXT NOT NULL,PRIMARY KEY(provider_hashtag_id,result_type));
